import codecs
import encodings
codecs.unregister(encodings.search_function)
try:
    codecs.lookup('')
except LookupError as error:
    print(type(error).__name__, error.args)
def second(name):
    raise AssertionError('removed search called')
def first(name):
    codecs.unregister(second)
    return None
codecs.register(first)
codecs.register(second)
try:
    codecs.lookup('')
except IndexError as error:
    print(type(error).__name__, error.args)
print(input())
